import json, os

MIMES = {
    ".stl": "model/stl",
    ".obj": "model/obj",
    ".glb": "model/gltf-binary",
    ".gltf": "model/gltf+json",
    ".3dm": "model/vnd.3dm",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".svg": "image/svg+xml",
    ".pdf": "application/pdf",
    ".zip": "application/zip",
    ".json": "application/json",
    ".csv": "text/csv",
    ".txt": "text/plain",
}

def get_mime_from_name(name):
    ext = os.path.splitext(name)[1].lower()
    return MIMES.get(ext, "application/octet-stream")

def update_blob_mime(blob, name):
    """Re-encode blob data URI with proper mime from filename."""
    if not blob or not blob.startswith("data:"):
        return blob
    # Extract the base64 part
    comma_idx = blob.index(",")
    base64_data = blob[comma_idx + 1:]
    mime = get_mime_from_name(name)
    return f"data:{mime};base64,{base64_data}"

def process_kit(kit):
    if "files" in kit:
        for f in kit["files"]:
            # Remove mime from file
            if "mime" in f:
                del f["mime"]
            # Update blob to use proper mime from filename
            if "blob" in f and f["blob"]:
                f["blob"] = update_blob_mime(f["blob"], f["name"])
    return kit

files_to_update = [
    "/workspaces/semio/compose/assets/compose/kit_metabolism.json",
    "/workspaces/semio/compose/assets/compose/kit_metabolism_diffed.json",
    "/workspaces/semio/compose/assets/compose/diff_kit_metabolism.json",
    "/workspaces/semio/compose/assets/compose/diff_kit_metabolism_inverted.json",
]

for filepath in files_to_update:
    if not os.path.exists(filepath):
        print(f"SKIP (not found): {filepath}")
        continue
    with open(filepath) as f:
        data = json.load(f)

    # Check if this is a kit or a diff
    if "files" in data:
        data = process_kit(data)

    # Handle diff files that have lists of file changes  
    if "files" in data and isinstance(data["files"], dict):
        for k in ["added", "removed", "updated"]:
            if k in data["files"]:
                for item in data["files"][k]:
                    if isinstance(item, dict):
                        if "mime" in item:
                            del item["mime"]
                        if "blob" in item and item["blob"]:
                            item["blob"] = update_blob_mime(item["blob"], item.get("name", ""))

    with open(filepath, "w") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)

    # Count remaining mime
    with open(filepath) as f:
        content = f.read()
    count = content.count('"mime"')
    print(f"Updated: {filepath} (remaining mime: {count})")

